  if($action==='profile'){$u=require_user();$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Enter your name.');db('UPDATE users SET name=?,phone=? WHERE id=?',[mb_substr($name,0,190),mb_substr($_POST['phone']??'',0,60),$u['id']]);flash('Profile updated.');redirect('user-profile.php');}
  if($action==='password'){$u=require_user();$hash=scalar('SELECT password_hash FROM users WHERE id=?',[$u['id']]);if(!password_verify($_POST['current_password']??'',$hash??''))throw new RuntimeException('Current password is incorrect.');if(strlen($_POST['password']??'')<12)throw new RuntimeException('Use at least 12 characters.');db('UPDATE users SET password_hash=?,session_version=session_version+1 WHERE id=?',[password_hash($_POST['password'],PASSWORD_DEFAULT),$u['id']]);$_SESSION['session_version']=(int)$u['session_version']+1;session_regenerate_id(true);flash('Password updated.');redirect('user-setting.php');}
