   $email=trim($_POST['email']??'');$identity=hash('sha256','reset|'.($_SERVER['REMOTE_ADDR']??''));if((int)scalar('SELECT COUNT(*) FROM login_attempts WHERE identity_hash=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 HOUR)',[$identity])>=5)throw new RuntimeException('Try again later.');db('INSERT INTO login_attempts(identity_hash) VALUES (?)',[$identity]);$u=row('SELECT id,email FROM users WHERE email=? AND active=1',[$email]);if($u){$token=bin2hex(random_bytes(32));db('DELETE FROM password_resets WHERE user_id=?',[$u['id']]);db('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES (?,?,DATE_ADD(NOW(),INTERVAL 1 HOUR))',[$u['id'],hash('sha256',$token)]);$link=setting('site_url','http://localhost'.url()).'reset-password.php?token='.$token;$message="Reset your password using this link (expires in one hour):\n".$link;if($config['environment']==='local')file_put_contents(__DIR__.'/../storage/reset-'.bin2hex(random_bytes(8)).'.txt','To: '.$email."\n".$message);else if(!mail($email,'Reset your password',$message,'From: '.setting('email')))error_log('Password reset delivery failed.');}flash('If an active account matches that email, password reset instructions have been sent.');redirect('forgot-password.php');}
  if($action==='reset'){if(strlen($_POST['password']??'')<12)throw new RuntimeException('Use at least 12 characters.');$conn->begin_transaction();try{$r=row('SELECT * FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() FOR UPDATE',[hash('sha256',$_POST['token']??'')]);if(!$r)throw new RuntimeException('This link has expired or has already been used.');db('UPDATE users SET password_hash=?,session_version=session_version+1 WHERE id=?',[password_hash($_POST['password'],PASSWORD_DEFAULT),$r['user_id']]);db('UPDATE password_resets SET used_at=NOW() WHERE user_id=?',[$r['user_id']]);$conn->commit();}catch(Throwable $e){$conn->rollback();throw $e;}flash('Password reset. You can now log in.');redirect('login.php');}
