else{$slug=$_GET['slug']??['about.php'=>'about','privacy.php'=>'privacy-policy-2','terms.php'=>'terms-and-conditions','return.php'=>'refund_returns'][$currentPage]??pathinfo($currentPage,PATHINFO_FILENAME);$post=row('SELECT * FROM content WHERE type="page" AND status="publish" AND slug=?',[$slug]);$pageTitle=$post['seo_title']??$post['title']??'Page not found';if($post){$pageTitle=$post['seo_title']?:$post['title'];$metaDescription=$post['meta_description']?:strip_tags(mb_substr($post['body'],0,180));$canonical=absolute_url('page.php?slug='.rawurlencode($post['slug']));}if(!$post){http_response_code(404);$view='missing';}}
